/// Add exact decimal numbers given as strings of any length and return the
/// exact sum as a string.
/// Each term is an optional leading '-', then one or more ASCII digits 0-9,
/// then optionally a '.' followed by one or more ASCII digits. Leading zeros
/// and trailing fractional zeros are allowed ("007.50"). Nothing else is
/// accepted: no '+', no spaces, no exponent, no '.' without digits on both
/// sides ("1." and ".5" are not terms). Terms may have hundreds of digits,
/// far beyond any fixed-width integer or float, and the sum must be exact.
/// The result is in canonical form: an integer part with no leading zeros
/// ("0" when it is zero), then, only if the fractional part is not zero, a
/// '.' and the fractional digits with trailing zeros removed; a '-' prefix
/// only when the sum is negative ("-0" is never returned).
/// The sum of an empty list is "0". If any term is not of the form above,
/// return the string "invalid".
/// >>> decimal_sum(vec![String::from("1.5"), String::from("2.25")])
/// String::from("3.75")
/// >>> decimal_sum(vec![String::from("99999999999999999999"), String::from("0.01"), String::from("-1")])
/// String::from("99999999999999999998.01")
fn decimal_sum(terms: Vec<String>) -> String {
    let mut parsed = Vec::new();
    let mut scale = 0;
    for t in &terms {
        let (neg, body) = match t.strip_prefix('-') {
            Some(b) => (true, b),
            None => (false, t.as_str()),
        };
        let (whole, frac) = match body.split_once('.') {
            Some((w, f)) => (w, Some(f)),
            None => (body, None),
        };
        if !all_digits(whole) || frac.map_or(false, |f| !all_digits(f)) {
            return String::from("invalid");
        }
        let frac = frac.unwrap_or("");
        scale = scale.max(frac.len());
        parsed.push((neg, whole, frac));
    }
    // signed column sums, least significant column first
    let mut cols: Vec<i64> = Vec::new();
    for (neg, whole, frac) in &parsed {
        let digits: Vec<i64> = whole.bytes().chain(frac.bytes()).map(|b| (b - b'0') as i64).collect();
        let pad = scale - frac.len();
        for (k, d) in digits.iter().rev().enumerate() {
            let i = k + pad;
            if cols.len() <= i {
                cols.resize(i + 1, 0);
            }
            cols[i] += if *neg { -d } else { *d };
        }
    }
    let mut digits = normalize(&cols);
    let negative = digits.is_none();
    if negative {
        let flipped: Vec<i64> = cols.iter().map(|c| -c).collect();
        digits = normalize(&flipped);
    }
    let mut digits = digits.unwrap();
    while digits.len() < scale + 1 {
        digits.push(0);
    }
    let text: String = digits.iter().rev().map(|d| char::from(b'0' + *d as u8)).collect();
    let split = text.len() - scale;
    let whole = text[..split].trim_start_matches('0');
    let frac = text[split..].trim_end_matches('0');
    let mut out = String::from(if whole.is_empty() { "0" } else { whole });
    if !frac.is_empty() {
        out.push('.');
        out.push_str(frac);
    }
    if negative && out != "0" {
        out.insert(0, '-');
    }
    out
}

fn all_digits(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit())
}

/// Carry the columns into digits 0..9; None when the total is negative.
fn normalize(cols: &[i64]) -> Option<Vec<i64>> {
    let mut out = Vec::new();
    let mut carry = 0i64;
    for c in cols {
        let v = c + carry;
        out.push(v.rem_euclid(10));
        carry = v.div_euclid(10);
    }
    if carry < 0 {
        return None;
    }
    while carry > 0 {
        out.push(carry % 10);
        carry /= 10;
    }
    Some(out)
}
